import React from "react";
import AccelLogo from "assets/img/accel_logo.png"; // remplace par ton logo
import "@fortawesome/fontawesome-free/css/all.min.css";

// Si tu n'as pas encore la CSS Font Awesome importée quelque part,
// ajoute dans src/index.js :  import "@fortawesome/fontawesome-free/css/all.min.css";

export default function Footer() {
  return (
    <footer className="bg-[#20264e] text-white">
      <div className="container mx-auto px-6 py-16 grid grid-cols-1 md:grid-cols-3 gap-12">

        {/* Col 1: Powered By */}
        <div className="text-center md:text-left">
          <h3 className="text-3xl font-semibold mb-6">Powered By</h3>
          <img
            src={AccelLogo}
            alt="Accel"
            className="h-20 w-auto mx-auto md:mx-0"
          />
        </div>

        {/* Col 2: Liens utiles */}
        <div>
          <h3 className="text-3xl font-semibold mb-6">Liens utiles</h3>
          <ul className="space-y-5 text-xl">
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-xl opacity-80"></i>
              <a href="#" className="hover:underline">Red Hat Enterprise Linux</a>
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-xl opacity-80"></i>
              <a href="#" className="hover:underline">Openshift AI</a>
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-xl opacity-80"></i>
              <a href="#" className="hover:underline">Heritage Cloud</a>
            </li>
          </ul>
        </div>

        {/* Col 3: Contacts */}
        <div>
          <h3 className="text-3xl font-semibold mb-6">Contacts</h3>
          <ul className="space-y-5 text-xl">
            <li className="flex items-center gap-4">
              <i className="fas fa-phone text-xl opacity-80"></i>
              33.000.00.00
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-envelope text-xl opacity-80"></i>
              xxx@example.com
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-globe text-xl opacity-80"></i>
              www.example.com
            </li>
          </ul>
        </div>
      </div>

      {/* Réseaux sociaux */}
      <div className="container mx-auto px-6 pb-14">
        <div className="flex justify-center md:justify-center gap-10 text-3xl">
          <a href="#" className="text-[#ff5a2a] hover:opacity-90"><i className="fab fa-facebook"></i></a>
          <a href="#" className="text-[#ff5a2a] hover:opacity-90"><i className="fab fa-linkedin"></i></a>
          <a href="#" className="text-[#ff5a2a] hover:opacity-90"><i className="fab fa-youtube"></i></a>
